  "order.ts": "export interface Order {\n  product: string;\n  pricing: {\n    quantity: number;\n    unitPrice: number;\n    discount: number; // percent\n  };\n}\n\nexport const PRODUCTS = ['Signal Lamp', 'Zone Breaker', 'Deferred Rocket'] as const;\n\nexport const INITIAL_ORDER: Order = {\n  product: 'Signal Lamp',\n  pricing: { quantity: 2, unitPrice: 49.9, discount: 10 },\n};\n\nexport function orderTotal(quantity: number, unitPrice: number, discount: number): number {\n  return Math.round(quantity * unitPrice * (1 - discount / 100) * 100) / 100;\n}\n",
  "reactive-order-form.ts": "import { CurrencyPipe } from '@angular/common';\nimport { Component, DestroyRef, inject, signal } from '@angular/core';\nimport { takeUntilDestroyed } from '@angular/core/rxjs-interop';\nimport { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';\nimport { MatFormFieldModule } from '@angular/material/form-field';\nimport { MatInputModule } from '@angular/material/input';\nimport { MatSelectModule } from '@angular/material/select';\nimport { INITIAL_ORDER, PRODUCTS, orderTotal } from './order';\n\n/** BEFORE: Reactive Forms – FormBuilder, nested FormGroup, a subscription for the total. */\n@Component({\n  selector: 'app-reactive-order-form',\n  imports: [CurrencyPipe, MatFormFieldModule, MatInputModule, MatSelectModule, ReactiveFormsModule],\n  template: `\n    <form [formGroup]=\"form\" class=\"demo-stack\">\n      <mat-form-field appearance=\"outline\">\n        <mat-label>Product</mat-label>\n        <mat-select formControlName=\"product\">\n          @for (p of products; track p) {\n            <mat-option [value]=\"p\">{{ p }}</mat-option>\n          }\n        </mat-select>\n      </mat-form-field>\n      <div formGroupName=\"pricing\" class=\"pricing\">\n        <mat-form-field appearance=\"outline\">\n          <mat-label>Quantity</mat-label>\n          <input matInput type=\"number\" formControlName=\"quantity\" />\n        </mat-form-field>\n        <mat-form-field appearance=\"outline\">\n          <mat-label>Unit price</mat-label>\n          <input matInput type=\"number\" formControlName=\"unitPrice\" />\n        </mat-form-field>\n        <mat-form-field appearance=\"outline\">\n          <mat-label>Discount %</mat-label>\n          <input matInput type=\"number\" formControlName=\"discount\" />\n        </mat-form-field>\n      </div>\n      <p class=\"total\">\n        Total: <strong>{{ total() | currency: 'EUR' }}</strong>\n      </p>\n    </form>\n  `,\n  styles: `\n    .pricing {\n      display: grid;\n      gap: 0 8px;\n      grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));\n    }\n    .total {\n      margin: 0 0 8px;\n      font: var(--mat-sys-title-medium);\n    }\n  `,\n})\nexport class ReactiveOrderForm {\n  readonly #fb = inject(FormBuilder);\n  readonly #destroyRef = inject(DestroyRef);\n  readonly products = PRODUCTS;\n  readonly subscriptions = 1;\n\n  readonly form = this.#fb.nonNullable.group({\n    product: [INITIAL_ORDER.product, Validators.required],\n    pricing: this.#fb.nonNullable.group({\n      quantity: [INITIAL_ORDER.pricing.quantity, [Validators.required, Validators.min(1)]],\n      unitPrice: [INITIAL_ORDER.pricing.unitPrice, Validators.min(0)],\n      discount: [INITIAL_ORDER.pricing.discount, [Validators.min(0), Validators.max(100)]],\n    }),\n  });\n\n  readonly total = signal(this.#calculate());\n\n  constructor() {\n    // A stream per derived value – and you must not forget the cleanup.\n    this.form.controls.pricing.valueChanges\n      .pipe(takeUntilDestroyed(this.#destroyRef))\n      .subscribe(() => this.total.set(this.#calculate()));\n  }\n\n  #calculate(): number {\n    const { quantity, unitPrice, discount } = this.form.controls.pricing.getRawValue();\n    return orderTotal(Number(quantity), Number(unitPrice), Number(discount));\n  }\n}\n",
  "signal-order-form.ts": "import { CurrencyPipe } from '@angular/common';\nimport { Component, computed, signal } from '@angular/core';\nimport { FormField, form, max, min, required } from '@angular/forms/signals';\nimport { MatFormFieldModule } from '@angular/material/form-field';\nimport { MatInputModule } from '@angular/material/input';\nimport { MatSelectModule } from '@angular/material/select';\nimport { INITIAL_ORDER, Order, PRODUCTS, orderTotal } from './order';\n\n/** AFTER: Signal Forms – interface + signal + form() + computed total. */\n@Component({\n  selector: 'app-signal-order-form',\n  imports: [CurrencyPipe, FormField, MatFormFieldModule, MatInputModule, MatSelectModule],\n  template: `\n    <form class=\"demo-stack\" novalidate>\n      <mat-form-field appearance=\"outline\">\n        <mat-label>Product</mat-label>\n        <mat-select [formField]=\"order.product\">\n          @for (p of products; track p) {\n            <mat-option [value]=\"p\">{{ p }}</mat-option>\n          }\n        </mat-select>\n      </mat-form-field>\n      <div class=\"pricing\">\n        <mat-form-field appearance=\"outline\">\n          <mat-label>Quantity</mat-label>\n          <input matInput type=\"number\" [formField]=\"order.pricing.quantity\" />\n        </mat-form-field>\n        <mat-form-field appearance=\"outline\">\n          <mat-label>Unit price</mat-label>\n          <input matInput type=\"number\" [formField]=\"order.pricing.unitPrice\" />\n        </mat-form-field>\n        <mat-form-field appearance=\"outline\">\n          <mat-label>Discount %</mat-label>\n          <input matInput type=\"number\" [formField]=\"order.pricing.discount\" />\n        </mat-form-field>\n      </div>\n      <p class=\"total\">\n        Total: <strong>{{ total() | currency: 'EUR' }}</strong>\n      </p>\n    </form>\n  `,\n  styles: `\n    .pricing {\n      display: grid;\n      gap: 0 8px;\n      grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));\n    }\n    .total {\n      margin: 0 0 8px;\n      font: var(--mat-sys-title-medium);\n    }\n  `,\n})\nexport class SignalOrderForm {\n  readonly products = PRODUCTS;\n  readonly subscriptions = 0;\n\n  readonly model = signal<Order>(structuredClone(INITIAL_ORDER));\n  readonly order = form(this.model, (path) => {\n    required(path.product);\n    min(path.pricing.quantity, 1);\n    min(path.pricing.unitPrice, 0);\n    min(path.pricing.discount, 0);\n    max(path.pricing.discount, 100);\n  });\n\n  readonly total = computed(() => {\n    const { quantity, unitPrice, discount } = this.model().pricing;\n    return orderTotal(quantity, unitPrice, discount);\n  });\n}\n",
